// Weekly housekeeping. No sales claims, no automatic price changes —
// only what the owner should check before the weekend rush.
const products = Array.isArray($input.first().json) ? $input.first().json : $input.all().map(i => i.json);
const DAY = 86400000;
const stale = products.filter(p => p.published && p.updated_at && (Date.now() - new Date(p.updated_at).getTime()) > 45 * DAY);
const noPhoto = products.filter(p => p.published && !p.photo_url);
const noPrice = products.filter(p => p.published && (p.price === null || p.price === undefined));
const byCategory = {};
for (const p of products.filter(p => p.published)) byCategory[p.category] = (byCategory[p.category] || 0) + 1;

const report = [
  `Published products: ${products.filter(p => p.published).length}`,
  `Drafts: ${products.filter(p => !p.published).length}`,
  '',
  `Prices to confirm: ${noPrice.length}`,
  noPrice.slice(0, 15).map(p => `• ${p.name_bn || p.name_en} (${p.slug})`).join('\n'),
  '',
  `Stock not touched for 45+ days: ${stale.length}`,
  stale.slice(0, 15).map(p => `• ${p.name_bn || p.name_en} — last update ${new Date(p.updated_at).toISOString().slice(0, 10)}`).join('\n'),
  '',
  `Products without a photo: ${noPhoto.length}`,
  '',
  `By category: ${Object.entries(byCategory).map(([k, v]) => `${k} ${v}`).join(' · ')}`,
  '',
  'Tip: photos and corrected prices are the two changes that most improve a phone visitor’s confidence.'
].filter(Boolean).join('\n');

return [{ json: { products: products.length, stale: stale.length, noPhoto: noPhoto.length, report } }];
